"""Dock allocation for the Spokecraft rider app."""
from dataclasses import dataclass


@dataclass
class Dock:
    dock_id: str
    station: str
    slots: int


class DockAllocatorV2:
    """Rebalanced allocator: picks the dock with the most free slots."""

    def __init__(self, docks):
        self.docks = list(docks)

    def best_dock(self, station: str) -> Dock:
        candidates = [d for d in self.docks if d.station == station and d.slots > 0]
        if not candidates:
            raise LookupError(station)
        return max(candidates, key=lambda d: d.slots)
